CREATE TABLE IF NOT EXISTS tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,title VARCHAR(250) NOT NULL,description TEXT NULL,status ENUM('NEW','ASSIGNED','IN_PROGRESS','WAITING','OVERDUE','COMPLETED','CANCELLED') NOT NULL DEFAULT 'NEW',priority ENUM('LOW','NORMAL','HIGH','URGENT') NOT NULL DEFAULT 'NORMAL',due_at DATETIME NULL,assigned_to BIGINT UNSIGNED NULL,created_by BIGINT UNSIGNED NOT NULL,entity_type VARCHAR(80) NULL,entity_id BIGINT UNSIGNED NULL,completed_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY ix_task_company_status(company_id,status,due_at),CONSTRAINT fk_task_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_task_assigned FOREIGN KEY(assigned_to) REFERENCES users(id),CONSTRAINT fk_task_creator FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS vehicles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,plate_no VARCHAR(40) NOT NULL,vehicle_type VARCHAR(80) NULL,capacity_weight DECIMAL(20,4) NULL,capacity_volume DECIMAL(20,4) NULL,refrigerated TINYINT(1) NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,UNIQUE KEY uq_vehicle_plate(company_id,plate_no),CONSTRAINT fk_vehicle_company FOREIGN KEY(company_id) REFERENCES companies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS routes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,code VARCHAR(50) NOT NULL,name VARCHAR(200) NOT NULL,region VARCHAR(150) NULL,salesperson_user_id BIGINT UNSIGNED NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,UNIQUE KEY uq_route_company_code(company_id,code),CONSTRAINT fk_route_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_route_salesperson FOREIGN KEY(salesperson_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS trips (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,trip_no VARCHAR(80) NOT NULL,trip_date DATE NOT NULL,route_id BIGINT UNSIGNED NULL,vehicle_id BIGINT UNSIGNED NULL,driver_user_id BIGINT UNSIGNED NULL,status ENUM('PLANNING','LOADING','GATE_CHECK','DISPATCHED','IN_ROUTE','PARTIAL','DELIVERED','FAILED','RETURN','SETTLEMENT_PENDING','CLOSED') NOT NULL DEFAULT 'PLANNING',odometer_out DECIMAL(20,2) NULL,odometer_in DECIMAL(20,2) NULL,expected_collection DECIMAL(20,2) NOT NULL DEFAULT 0,actual_collection DECIMAL(20,2) NOT NULL DEFAULT 0,inventory_variance DECIMAL(20,4) NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_trip_company_no(company_id,trip_no),KEY ix_trip_date(company_id,trip_date,status),CONSTRAINT fk_trip_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_trip_route FOREIGN KEY(route_id) REFERENCES routes(id),CONSTRAINT fk_trip_vehicle FOREIGN KEY(vehicle_id) REFERENCES vehicles(id),CONSTRAINT fk_trip_driver FOREIGN KEY(driver_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS trip_stops (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,trip_id BIGINT UNSIGNED NOT NULL,sequence_no INT NOT NULL,customer_party_id BIGINT UNSIGNED NOT NULL,sales_invoice_id BIGINT UNSIGNED NULL,status ENUM('PLANNED','ARRIVED','DELIVERED','PARTIAL','FAILED','RETURNED') NOT NULL DEFAULT 'PLANNED',delivered_at DATETIME NULL,receiver_name VARCHAR(200) NULL,pod_note TEXT NULL,latitude DECIMAL(10,7) NULL,longitude DECIMAL(10,7) NULL,UNIQUE KEY uq_trip_stop_seq(trip_id,sequence_no),CONSTRAINT fk_stop_trip FOREIGN KEY(trip_id) REFERENCES trips(id) ON DELETE CASCADE,CONSTRAINT fk_stop_customer FOREIGN KEY(customer_party_id) REFERENCES parties(id),CONSTRAINT fk_stop_invoice FOREIGN KEY(sales_invoice_id) REFERENCES sales_invoices(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS commission_rules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,basis ENUM('GROSS_SALES','NET_SALES','GROSS_PROFIT','COLLECTION','TARGET') NOT NULL,base_rate DECIMAL(10,4) NOT NULL DEFAULT 0,collection_based TINYINT(1) NOT NULL DEFAULT 0,rule_json JSON NULL,is_active TINYINT(1) NOT NULL DEFAULT 1,CONSTRAINT fk_comm_rule_company FOREIGN KEY(company_id) REFERENCES companies(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE IF NOT EXISTS commission_results (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,salesperson_user_id BIGINT UNSIGNED NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,basis_amount DECIMAL(20,2) NOT NULL,eligible_amount DECIMAL(20,2) NOT NULL,rate DECIMAL(10,4) NOT NULL,commission_amount DECIMAL(20,2) NOT NULL,adjustment_amount DECIMAL(20,2) NOT NULL DEFAULT 0,status ENUM('CALCULATED','REVIEWED','APPROVED','PAID','CLAWED_BACK') NOT NULL DEFAULT 'CALCULATED',details_json JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY ix_comm_user_period(company_id,salesperson_user_id,period_start,period_end),CONSTRAINT fk_comm_company FOREIGN KEY(company_id) REFERENCES companies(id),CONSTRAINT fk_comm_user FOREIGN KEY(salesperson_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;